public abstract class WildAssemblyTerminal : AssemblyTerminal {
	public static readonly Pattern PAT_WILD = Pattern.compile("`(?<spec>[^`]*)`");

	public WildAssemblyTerminal(string name) : base(name)
    {
	}

	protected Pattern getPattern() {
		return PAT_WILD;
	}

	/* @Override */
	public Collection<AssemblyParseToken> match(string buffer, int pos,
			AssemblyGrammar grammar, AssemblyNumericSymbols symbols) {
		Matcher matcher = getPattern().matcher(buffer).region(pos, buffer.length());
		if (!matcher.lookingAt()) {
			return List.of();
		}
		return List.of(
			new WildAssemblyParseToken(grammar, this, matcher.group(), matcher.group("spec")));
	}

	/* @Override */
	public Collection<string> getSuggestions(string got, AssemblyNumericSymbols symbols) {
		return List.of("`Q1`");
	}
}
